powerpagecomponent.content:
{
  "description": "Allowlist of columns the Web API may act on for al_outcomecase: the case status alone, which is the one value a page needs to re-read to correct a stale badge. Every other column stays off the list, and the table carries no write permission at all, so this grants a read of one column and no write of anything.",
  "value": "al_casestatus"
}
